=== public/css/styles.css ===
:root{
  --ink:#16130f;
  --ink-soft:#4a443c;
  --muted:#857c70;
  --paper:#f5f1e9;
  --paper-2:#efe9dd;
  --card:#fffdf8;
  --line:#e4dccc;
  --brand:#e8491d;
  --brand-dark:#c63a14;
  --gold:#e0a52e;
  --green:#1f8a5b;
  --radius:16px;
  --radius-sm:10px;
  --shadow-sm:0 2px 8px rgba(22,19,15,.06);
  --shadow:0 10px 30px rgba(22,19,15,.10);
  --shadow-lg:0 24px 60px rgba(22,19,15,.18);
  --font-head:'Sora',sans-serif;
  --font-body:'DM Sans',sans-serif;
}

*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:var(--font-body);
  background:var(--paper);
  color:var(--ink);
  line-height:1.55;
  -webkit-font-smoothing:antialiased;
  min-height:100vh;
  background-image:
    radial-gradient(circle at 12% -5%, rgba(232,73,29,.06), transparent 42%),
    radial-gradient(circle at 92% 8%, rgba(224,165,46,.07), transparent 40%);
}

/* ---------- Loading ---------- */
.loading{
  position:fixed;inset:0;background:var(--paper);
  display:flex;flex-direction:column;gap:22px;align-items:center;justify-content:center;z-index:200;
}
.loading-mark{color:var(--brand);animation:bob 1.4s ease-in-out infinite}
.loading p{color:var(--muted);letter-spacing:.04em;text-transform:lowercase}
@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}

/* ---------- App shell ---------- */
.app{display:block}
.icon-btn{background:none;border:none;cursor:pointer;color:inherit;display:inline-flex;align-items:center;justify-content:center}

/* ---------- Header ---------- */
.topbar{
  background:var(--ink);color:var(--paper);
  display:flex;align-items:center;justify-content:center;gap:8px;
  font-size:13px;padding:8px 16px;letter-spacing:.02em;
  position:relative;overflow:hidden;
}
.topbar .marquee{display:inline-flex;gap:40px;white-space:nowrap;animation:slide 26s linear infinite}
.topbar .marquee span{opacity:.85}
.topbar .marquee b{color:var(--gold);font-weight:700}
@keyframes slide{from{transform:translateX(0)}to{transform:translateX(-50%)}}

.site-header{
  position:sticky;top:0;z-index:50;
  background:rgba(245,241,233,.86);
  backdrop-filter:blur(14px);
  border-bottom:1px solid var(--line);
}
.header-inner{
  max-width:1240px;margin:0 auto;padding:14px 24px;
  display:flex;align-items:center;gap:20px;
}
.brand{display:flex;align-items:center;gap:11px;cursor:pointer;flex-shrink:0}
.brand-mark{
  width:42px;height:42px;border-radius:12px;
  background:linear-gradient(135deg,var(--brand),var(--gold));
  display:flex;align-items:center;justify-content:center;color:#fff;
  box-shadow:var(--shadow-sm);
}
.brand-name{font-family:var(--font-head);font-weight:800;font-size:19px;letter-spacing:-.01em;line-height:1.05}
.brand-name small{display:block;font-family:var(--font-body);font-weight:500;font-size:11px;color:var(--muted);letter-spacing:.14em;text-transform:uppercase}

.search{
  flex:1;max-width:520px;position:relative;
}
.search input{
  width:100%;padding:13px 18px 13px 44px;border:1.5px solid var(--line);
  border-radius:999px;background:var(--card);font-family:var(--font-body);font-size:15px;color:var(--ink);
  transition:border-color .2s,box-shadow .2s;
}
.search input:focus{outline:none;border-color:var(--brand);box-shadow:0 0 0 4px rgba(232,73,29,.12)}
.search .search-ic{position:absolute;left:16px;top:50%;transform:translateY(-50%);color:var(--muted)}

.header-actions{display:flex;align-items:center;gap:8px;margin-left:auto}
.hbtn{
  display:flex;align-items:center;gap:8px;padding:11px 15px;border-radius:999px;
  border:1.5px solid transparent;background:transparent;cursor:pointer;font-family:var(--font-head);
  font-weight:600;font-size:14px;color:var(--ink);transition:all .18s;
}
.hbtn:hover{background:var(--paper-2);border-color:var(--line)}
.cart-badge{
  min-width:22px;height:22px;padding:0 6px;border-radius:999px;background:var(--brand);color:#fff;
  font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;
  font-family:var(--font-head);
}
.avatar{
  width:40px;height:40px;border-radius:50%;background:var(--ink);color:var(--paper);
  display:flex;align-items:center;justify-content:center;font-family:var(--font-head);font-weight:700;font-size:15px;
}
.admin-tag{background:var(--gold);color:#3a2a00}

/* ---------- Category strip ---------- */
.cat-strip{
  border-bottom:1px solid var(--line);background:var(--card);
}
.cat-inner{max-width:1240px;margin:0 auto;padding:12px 24px;display:flex;gap:10px;overflow-x:auto;scrollbar-width:none}
.cat-inner::-webkit-scrollbar{display:none}
.cat-chip{
  padding:9px 18px;border-radius:999px;border:1.5px solid var(--line);background:var(--paper);
  font-family:var(--font-head);font-weight:600;font-size:13.5px;color:var(--ink-soft);cursor:pointer;white-space:nowrap;transition:all .18s;
}
.cat-chip:hover{border-color:var(--ink);color:var(--ink)}
.cat-chip.active{background:var(--ink);color:var(--paper);border-color:var(--ink)}

/* ---------- Hero ---------- */
.hero{max-width:1240px;margin:0 auto;padding:40px 24px 26px}
.hero-grid{
  display:grid;grid-template-columns:1.15fr .85fr;gap:24px;align-items:stretch;
}
.hero-main{
  position:relative;border-radius:24px;overflow:hidden;min-height:340px;
  background:linear-gradient(120deg,#1c1813 0%,#2a221a 100%);color:#fff;
  display:flex;flex-direction:column;justify-content:center;padding:44px;
}
.hero-kicker{font-family:var(--font-head);font-weight:600;letter-spacing:.22em;text-transform:uppercase;font-size:13px;color:var(--gold);margin-bottom:16px}
.hero-title{font-family:var(--font-head);font-weight:800;font-size:clamp(30px,4.4vw,52px);line-height:1.02;letter-spacing:-.02em}
.hero-title em{font-style:normal;color:var(--brand)}
.hero-sub{margin-top:16px;font-size:17px;color:rgba(255,255,255,.78);max-width:420px}
.hero-cta{margin-top:26px;display:flex;gap:12px;flex-wrap:wrap}
.hero-badge-float{
  position:absolute;right:34px;top:34px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);
  padding:12px 18px;border-radius:14px;font-family:var(--font-head);font-weight:700;font-size:15px;
}
.hero-side{display:grid;grid-template-rows:1fr 1fr;gap:24px}
.hero-card{
  border-radius:24px;padding:26px;display:flex;flex-direction:column;justify-content:center;position:relative;overflow:hidden;
}
.hero-card.a{background:linear-gradient(135deg,var(--brand),#f06a3a);color:#fff}
.hero-card.b{background:linear-gradient(135deg,#1f8a5b,#2aa574);color:#fff}
.hero-card h4{font-family:var(--font-head);font-weight:700;font-size:22px;letter-spacing:-.01em}
.hero-card p{margin-top:8px;font-size:14px;opacity:.9}
.hero-card .big{font-family:var(--font-head);font-weight:800;font-size:38px;margin-top:6px;letter-spacing:-.02em}
.hero-card .ic{position:absolute;right:-8px;bottom:-10px;opacity:.22;font-size:78px}

/* ---------- Buttons ---------- */
.btn{
  font-family:var(--font-head);font-weight:700;font-size:15px;cursor:pointer;
  border:none;border-radius:12px;padding:14px 22px;display:inline-flex;align-items:center;justify-content:center;gap:9px;
  transition:transform .12s,box-shadow .2s,background .2s;white-space:nowrap;
}
.btn:active{transform:scale(.97)}
.btn-primary{background:var(--brand);color:#fff;box-shadow:0 6px 18px rgba(232,73,29,.32)}
.btn-primary:hover{background:var(--brand-dark);box-shadow:0 10px 24px rgba(232,73,29,.4)}
.btn-dark{background:var(--ink);color:var(--paper)}
.btn-dark:hover{background:#000}
.btn-ghost{background:var(--paper-2);color:var(--ink)}
.btn-ghost:hover{background:var(--line)}
.btn-light{background:#fff;color:var(--ink)}
.btn-light:hover{background:var(--paper-2)}
.btn-sm{padding:10px 16px;font-size:14px;border-radius:10px}
.btn:disabled{opacity:.5;cursor:not-allowed}

/* ---------- Section ---------- */
.section{max-width:1240px;margin:0 auto;padding:34px 24px}
.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:22px;flex-wrap:wrap}
.section-title{font-family:var(--font-head);font-weight:800;font-size:clamp(24px,3vw,32px);letter-spacing:-.02em}
.section-title span{color:var(--muted);font-weight:600;font-size:16px}
.section-sub{color:var(--muted);font-size:15px;margin-top:2px}
.filter-note{color:var(--brand);font-family:var(--font-head);font-weight:600;font-size:14px;background:rgba(232,73,29,.1);padding:7px 14px;border-radius:999px}

/* ---------- Product grid ---------- */
.grid{
  display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:20px;
}
.card{
  background:var(--card);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;
  cursor:pointer;transition:transform .25s cubic-bezier(.2,.8,.2,1),box-shadow .25s,border-color .25s;
  animation:fadeUp .5s both;
}
@keyframes fadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}
.card:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg);border-color:transparent}
.card-media{position:relative;aspect-ratio:1/1;overflow:hidden;background:var(--paper-2)}
.card-media img{width:100%;height:100%;object-fit:cover;transition:transform .5s cubic-bezier(.2,.8,.2,1)}
.card:hover .card-media img{transform:scale(1.07)}
.card-tag{
  position:absolute;top:12px;left:12px;background:rgba(22,19,15,.82);color:#fff;backdrop-filter:blur(6px);
  font-family:var(--font-head);font-weight:600;font-size:11.5px;letter-spacing:.03em;padding:6px 12px;border-radius:999px;
}
.card-add{
  position:absolute;bottom:12px;right:12px;width:44px;height:44px;border-radius:12px;background:var(--brand);color:#fff;
  border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:var(--shadow);
  transform:translateY(12px);opacity:0;transition:all .25s;
}
.card:hover .card-add{transform:translateY(0);opacity:1}
.card-add:hover{background:var(--brand-dark)}
.card-body{padding:16px 16px 18px}
.card-cat{font-family:var(--font-head);font-weight:600;font-size:11.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--brand)}
.card-name{font-family:var(--font-head);font-weight:700;font-size:16px;line-height:1.25;margin-top:5px;letter-spacing:-.01em}
.card-desc{color:var(--muted);font-size:13.5px;margin-top:7px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.card-foot{display:flex;align-items:center;justify-content:space-between;margin-top:14px;gap:10px}
.price{font-family:var(--font-head);font-weight:800;font-size:19px;letter-spacing:-.02em}
.price .old{font-size:13px;font-weight:600;color:var(--muted);text-decoration:line-through;margin-right:7px}
.add-full{background:var(--ink);color:#fff;border:none;border-radius:11px;padding:11px 16px;font-family:var(--font-head);font-weight:700;font-size:14px;cursor:pointer;display:flex;align-items:center;gap:7px;transition:background .2s}
.add-full:hover{background:var(--brand)}

/* ---------- Footer ---------- */
.site-footer{background:var(--ink);color:var(--paper);margin-top:40px;padding:44px 24px 26px}
.footer-inner{max-width:1240px;margin:0 auto;display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:30px}
.site-footer h5{font-family:var(--font-head);font-weight:700;font-size:14px;letter-spacing:.04em;margin-bottom:14px;color:var(--gold)}
.site-footer a,.site-footer span{display:block;color:rgba(255,255,255,.62);font-size:14px;margin-bottom:9px;cursor:pointer;transition:color .18s}
.site-footer a:hover{color:#fff}
.footer-brand p{color:rgba(255,255,255,.6);font-size:14px;margin-top:12px;max-width:280px}
.footer-bottom{max-width:1240px;margin:30px auto 0;padding-top:20px;border-top:1px solid rgba(255,255,255,.12);font-size:13px;color:rgba(255,255,255,.5);display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px}

/* ---------- Modals / overlays ---------- */
.overlay{
  position:fixed;inset:0;background:rgba(22,19,15,.5);backdrop-filter:blur(4px);
  display:flex;align-items:center;justify-content:center;padding:20px;z-index:100;animation:fade .2s;
}
@keyframes fade{from{opacity:0}to{opacity:1}}
.modal{
  background:var(--card);border-radius:22px;box-shadow:var(--shadow-lg);width:100%;max-width:440px;
  max-height:92vh;overflow:auto;animation:pop .28s cubic-bezier(.2,.9,.3,1.2);
}
@keyframes pop{from{opacity:0;transform:scale(.94) translateY(10px)}to{opacity:1;transform:scale(1) translateY(0)}}
.modal-lg{max-width:900px}
.modal-xl{max-width:1120px}
.modal-head{padding:22px 26px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}
.modal-head h3{font-family:var(--font-head);font-weight:800;font-size:20px;letter-spacing:-.01em}
.modal-body{padding:24px 26px}
.modal-close{width:38px;height:38px;border-radius:10px;background:var(--paper-2);display:flex;align-items:center;justify-content:center;cursor:pointer;border:none;color:var(--ink);transition:background .18s}
.modal-close:hover{background:var(--line)}

/* ---------- Auth ---------- */
.auth-tabs{display:flex;gap:8px;background:var(--paper-2);padding:6px;border-radius:14px;margin-bottom:22px}
.auth-tab{flex:1;padding:12px;border:none;background:transparent;border-radius:10px;font-family:var(--font-head);font-weight:700;font-size:15px;color:var(--muted);cursor:pointer;transition:all .2s}
.auth-tab.active{background:var(--card);color:var(--ink);box-shadow:var(--shadow-sm)}
.auth-quick{margin-top:22px;padding-top:20px;border-top:1px dashed var(--line)}
.auth-quick p{font-size:13px;color:var(--muted);text-align:center;margin-bottom:12px}
.auth-quick-row{display:flex;flex-direction:column;gap:10px}
.quick-btn{display:flex;align-items:center;gap:12px;padding:12px 14px;border:1.5px solid var(--line);border-radius:12px;background:var(--paper);cursor:pointer;text-align:left;transition:all .18s;font-family:var(--font-body)}
.quick-btn:hover{border-color:var(--ink);background:var(--card)}
.quick-btn .role{font-family:var(--font-head);font-weight:700;font-size:14px;color:var(--ink)}
.quick-btn .cred{font-size:12.5px;color:var(--muted)}
.quick-btn .go{margin-left:auto;color:var(--brand);font-weight:700;font-family:var(--font-head)}

/* ---------- Forms ---------- */
.field{margin-bottom:16px}
.field label{display:block;font-family:var(--font-head);font-weight:600;font-size:13px;margin-bottom:7px;color:var(--ink-soft)}
.field input,.field textarea,.field select{
  width:100%;padding:13px 15px;border:1.5px solid var(--line);border-radius:12px;background:var(--paper);
  font-family:var(--font-body);font-size:15px;color:var(--ink);transition:border-color .2s,box-shadow .2s;
}
.field input:focus,.field textarea:focus,.field select:focus{outline:none;border-color:var(--brand);box-shadow:0 0 0 4px rgba(232,73,29,.12);background:var(--card)}
.field textarea{resize:vertical;min-height:80px}
.field-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.form-err{background:rgba(220,50,50,.08);border:1px solid rgba(220,50,50,.25);color:#c02626;padding:11px 14px;border-radius:10px;font-size:13.5px;margin-bottom:14px}

/* ---------- Product detail ---------- */
.pd-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px;align-items:start}
.pd-media{border-radius:18px;overflow:hidden;aspect-ratio:1/1;background:var(--paper-2);position:relative}
.pd-media img{width:100%;height:100%;object-fit:cover}
.pd-cat{font-family:var(--font-head);font-weight:600;font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--brand)}
.pd-name{font-family:var(--font-head);font-weight:800;font-size:30px;letter-spacing:-.02em;line-height:1.1;margin-top:8px}
.pd-desc{color:var(--ink-soft);font-size:16px;margin-top:14px}
.pd-price{font-family:var(--font-head);font-weight:800;font-size:34px;margin-top:22px;letter-spacing:-.02em}
.pd-stock{margin-top:6px;font-size:14px;color:var(--muted)}
.pd-stock .ok{color:var(--green);font-weight:600}
.pd-stock .out{color:#c02626;font-weight:600}
.pd-qty{display:flex;align-items:center;gap:14px;margin-top:24px}
.qty{display:flex;align-items:center;border:1.5px solid var(--line);border-radius:12px;overflow:hidden}
.qty button{width:44px;height:48px;border:none;background:var(--paper);cursor:pointer;font-size:22px;color:var(--ink);transition:background .15s}
.qty button:hover{background:var(--paper-2)}
.qty span{width:48px;text-align:center;font-family:var(--font-head);font-weight:700;font-size:17px}
.pd-actions{display:flex;gap:12px;margin-top:22px;flex-wrap:wrap}

/* ---------- Cart ---------- */
.cart-item{display:grid;grid-template-columns:74px 1fr auto;gap:16px;align-items:center;padding:16px 0;border-bottom:1px solid var(--line)}
.cart-item img{width:74px;height:74px;border-radius:12px;object-fit:cover;background:var(--paper-2)}
.ci-name{font-family:var(--font-head);font-weight:700;font-size:15px}
.ci-price{color:var(--muted);font-size:14px;margin-top:3px}
.ci-right{text-align:right}
.ci-subtotal{font-family:var(--font-head);font-weight:700;font-size:16px}
.ci-remove{background:none;border:none;color:var(--muted);cursor:pointer;margin-top:10px;font-size:13px;display:flex;align-items:center;gap:5px;justify-content:flex-end;transition:color .18s}
.ci-remove:hover{color:#c02626}
.qty-sm{margin-top:10px}
.qty-sm button{width:32px;height:32px;font-size:18px}
.qty-sm span{width:36px;font-size:15px}
.cart-empty{text-align:center;padding:50px 20px}
.cart-empty .big{font-size:60px;margin-bottom:14px}
.cart-empty h4{font-family:var(--font-head);font-weight:700;font-size:20px}
.cart-empty p{color:var(--muted);margin:8px 0 20px}
.summary{background:var(--paper);border-radius:16px;padding:22px;margin-top:22px}
.sum-row{display:flex;justify-content:space-between;font-size:15px;margin-bottom:12px;color:var(--ink-soft)}
.sum-row.total{border-top:1px solid var(--line);padding-top:14px;margin-top:6px;font-family:var(--font-head);font-weight:800;font-size:20px;color:var(--ink)}
.checkout-steps{display:flex;gap:10px;margin-bottom:22px}
.step-pill{flex:1;text-align:center;padding:12px;border-radius:12px;background:var(--paper-2);font-family:var(--font-head);font-weight:600;font-size:13px;color:var(--muted)}
.step-pill.active{background:var(--ink);color:var(--paper)}

/* ---------- Orders / admin ---------- */
.tabs{display:flex;gap:8px;margin-bottom:22px;flex-wrap:wrap}
.tab{padding:11px 20px;border:1.5px solid var(--line);background:var(--card);border-radius:999px;font-family:var(--font-head);font-weight:600;font-size:14px;cursor:pointer;transition:all .18s}
.tab.active{background:var(--ink);color:var(--paper);border-color:var(--ink)}
.order-card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px;transition:box-shadow .2s}
.order-card:hover{box-shadow:var(--shadow)}
.order-top{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:16px}
.order-id{font-family:var(--font-head);font-weight:800;font-size:16px}
.order-meta{color:var(--muted);font-size:13px;margin-top:3px}
.status{font-family:var(--font-head);font-weight:700;font-size:12.5px;padding:7px 14px;border-radius:999px;letter-spacing:.02em}
.status-Pendente{background:rgba(224,165,46,.16);color:#9a6b0f}
.status-Pago{background:rgba(31,138,91,.16);color:var(--green)}
.status-Em\ preparo{background:rgba(31,138,91,.16);color:var(--green)}
.status-Enviado{background:rgba(40,110,190,.16);color:#1f5aa0}
.status-Entregue{background:rgba(22,19,15,.1);color:var(--ink)}
.status-Cancelado{background:rgba(220,50,50,.14);color:#c02626}
.order-items{border-top:1px solid var(--line);padding-top:14px}
.oi{display:flex;justify-content:space-between;gap:10px;font-size:14px;padding:5px 0;color:var(--ink-soft)}
.oi b{color:var(--ink);font-weight:600}
.order-foot{display:flex;justify-content:space-between;align-items:center;margin-top:14px;flex-wrap:wrap;gap:12px}
.order-foot .tot{font-family:var(--font-head);font-weight:800;font-size:18px}
.order-actions{display:flex;gap:8px;align-items:center}
.order-select{padding:10px 14px;border:1.5px solid var(--line);border-radius:10px;font-family:var(--font-head);font-weight:600;font-size:14px;background:var(--paper);cursor:pointer;color:var(--ink)}

/* ---------- Admin dashboard ---------- */
.admin-wrap{max-width:1240px;margin:0 auto;padding:30px 24px}
.admin-top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:26px;flex-wrap:wrap}
.admin-top h2{font-family:var(--font-head);font-weight:800;font-size:clamp(24px,3vw,32px);letter-spacing:-.02em}
.admin-top p{color:var(--muted);margin-top:4px}
.stat-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin-bottom:30px}
.stat{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:22px;position:relative;overflow:hidden}
.stat .label{font-family:var(--font-head);font-weight:600;font-size:13px;color:var(--muted);letter-spacing:.03em}
.stat .value{font-family:var(--font-head);font-weight:800;font-size:34px;letter-spacing:-.02em;margin-top:8px}
.stat .ic{position:absolute;right:16px;top:18px;font-size:26px;opacity:.5}
.stat.accent{background:linear-gradient(135deg,var(--brand),var(--brand-dark));border:none;color:#fff}
.stat.accent .label,.stat.accent .ic{color:rgba(255,255,255,.85)}
.admin-actions{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}

.table-wrap{background:var(--card);border:1px solid var(--line);border-radius:16px;overflow:auto}
table{width:100%;border-collapse:collapse;min-width:640px}
th{text-align:left;font-family:var(--font-head);font-weight:700;font-size:12px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);padding:15px 18px;border-bottom:1px solid var(--line);background:var(--paper)}
td{padding:15px 18px;border-bottom:1px solid var(--line);font-size:14.5px;vertical-align:middle}
tr:last-child td{border-bottom:none}
tbody tr{transition:background .15s}
tbody tr:hover{background:var(--paper)}
.td-prod{display:flex;align-items:center;gap:12px}
.td-prod img{width:44px;height:44px;border-radius:9px;object-fit:cover}
.row-actions{display:flex;gap:8px}
.rbtn{width:38px;height:38px;border-radius:10px;border:1.5px solid var(--line);background:var(--card);cursor:pointer;display:flex;align-items:center;justify-content:center;color:var(--ink-soft);transition:all .16s}
.rbtn:hover{background:var(--ink);color:#fff;border-color:var(--ink)}
.rbtn.del:hover{background:#c02626;border-color:#c02626}

/* ---------- Toasts ---------- */
.toasts{position:fixed;bottom:24px;right:24px;z-index:300;display:flex;flex-direction:column;gap:10px;max-width:340px}
.toast{
  background:var(--ink);color:var(--paper);padding:14px 18px;border-radius:13px;box-shadow:var(--shadow-lg);
  font-family:var(--font-head);font-weight:600;font-size:14px;display:flex;align-items:center;gap:10px;
  animation:slideIn .3s cubic-bezier(.2,.9,.3,1.2);
}
@keyframes slideIn{from{opacity:0;transform:translateX(40px)}to{opacity:1;transform:translateX(0)}}
.toast.success{background:var(--green)}
.toast.error{background:#c02626}
.toast .dot{width:9px;height:9px;border-radius:50%;background:#fff;flex-shrink:0}

.empty-state{text-align:center;padding:60px 20px;color:var(--muted)}
.empty-state .big{font-size:56px;margin-bottom:14px}
.empty-state h4{font-family:var(--font-head);font-weight:700;font-size:20px;color:var(--ink)}
.empty-state p{margin-top:6px}

/* ---------- Responsive ---------- */
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .hero-side{grid-template-rows:none;grid-template-columns:1fr 1fr}
  .footer-inner{grid-template-columns:1fr 1fr}
  .pd-grid{grid-template-columns:1fr}
  .search{order:3;max-width:none;flex-basis:100%}
  .header-inner{flex-wrap:wrap;gap:12px}
}
@media (max-width:560px){
  .hero-side{grid-template-columns:1fr}
  .footer-inner{grid-template-columns:1fr}
  .field-row{grid-template-columns:1fr}
  .hbtn span.hbtn-label{display:none}
  .hbtn{padding:11px}
  .grid{grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:14px}
  .section{padding:24px 16px}
  .hero{padding:24px 16px}
  .brand-name{font-size:16px}
}

