function toast(msg, type) {
  const wrap = $('#toasts');
  const el = document.createElement('div');
  el.className = 'toast ' + (type || '');
  el.innerHTML = '<span class="dot"></span>' + escapeHtml(msg);
  wrap.appendChild(el);
  setTimeout(() => {
    el.style.transition = 'opacity .3s, transform .3s';
    el.style.opacity = '0';
    el.style.transform = 'translateX(40px)';
    setTimeout(() => el.remove(), 300);
  }, 2600);
}

function imgWithFallback(src) {
  return '<img src="' + src + '" alt="" loading="lazy" onerror="this.onerror=null;this.src=\'https://picsum.photos/seed/fallback/' + (Math.random()*1000|0) + '/400/400\';">';
}

